from __future__ import annotations

import json
import pathlib
import shutil
import subprocess


ROOT = pathlib.Path(__file__).resolve().parent
OCTAVE_SCRIPT = (
    ROOT / "source" / "sciencebench_task005" / "task005_public_reproduction.m"
)
OUTPUTS = ROOT / "outputs"
REPORT_PATH = OUTPUTS / "reproduction_report.json"
STANDARD_STATUSES = {
    "workflow_completed",
    "pre_fix_expected_failure",
    "post_fix_success",
    "runner_failure",
}


def emit_runner_failure(error_type: str, error: str) -> int:
    report = {
        "workflow": "edited MRS SDAT loading and common-reference diagnostics",
        "status": "runner_failure",
        "error_type": error_type,
        "error": error,
    }
    payload = json.dumps(report, indent=2, sort_keys=True, allow_nan=False) + "\n"
    OUTPUTS.mkdir(exist_ok=True)
    REPORT_PATH.write_text(payload, encoding="utf-8")
    print(payload, end="")
    return 2


def load_report() -> dict[str, object]:
    def reject_constant(value: str) -> None:
        raise ValueError(f"Non-finite JSON constant: {value}")

    report = json.loads(
        REPORT_PATH.read_text(encoding="utf-8"), parse_constant=reject_constant
    )
    if not isinstance(report, dict) or report.get("status") not in STANDARD_STATUSES:
        raise ValueError("Octave report did not contain a standard public status.")
    return report


def main() -> int:
    OUTPUTS.mkdir(exist_ok=True)
    REPORT_PATH.unlink(missing_ok=True)
    octave = shutil.which("octave")
    if octave is None:
        return emit_runner_failure(
            "MissingDependency",
            "GNU Octave is required for this task. Run in the Octave task image.",
        )

    try:
        completed = subprocess.run(
            [octave, "--no-gui", "--quiet", str(OCTAVE_SCRIPT)],
            cwd=ROOT,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            check=False,
            timeout=120,
        )
    except subprocess.TimeoutExpired as exc:
        return emit_runner_failure(
            type(exc).__name__, "Octave public workflow timed out."
        )
    except OSError as exc:
        return emit_runner_failure(type(exc).__name__, str(exc))

    print(completed.stdout, end="")
    try:
        report = load_report()
    except (OSError, ValueError) as exc:
        return emit_runner_failure(type(exc).__name__, str(exc))

    if report["status"] == "runner_failure":
        return 2
    if completed.returncode != 0:
        return emit_runner_failure(
            "OctaveProcessError",
            f"Octave exited with code {completed.returncode} without a runner_failure report.",
        )
    return 0 if report["status"] in {"workflow_completed", "post_fix_success"} else 1


if __name__ == "__main__":
    raise SystemExit(main())
function [MRSCont] = osp_LoadSDAT(MRSCont)
%% [MRSCont] = osp_LoadSDAT(MRSCont)
%   This function reads raw (but coil-combined) data from Philips SDAT files.
%
%   USAGE:
%       [MRSCont] = osp_LoadSDAT(MRSCont);
%
%   INPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   OUTPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   AUTHOR:
%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-02-20)
%       goeltzs1@jhmi.edu
%   
%   CREDITS:    
%       This code is based on numerous functions from the FID-A toolbox by
%       Dr. Jamie Near (McGill University)
%       https://github.com/CIC-methods/FID-A
%       Simpson et al., Magn Reson Med 77:23-33 (2017)
%
%   HISTORY:
%       2019-02-20: First version of the code.

% Close any remaining open figures
close all;
warning('off','all');
if MRSCont.flags.hasMM %re_mm adding functionality to load MM data
    if ((length(MRSCont.files_mm) == 1) && (MRSCont.nDatasets(1)>1))   %re_mm seems like specificy one MM file for a batch is also an option to plan to accomodate
        for kk=2:MRSCont.nDatasets(1) %re_mm 
            MRSCont.files_mm{kk} = MRSCont.files_mm{1}; % re_mm allowable to specify one MM file for the whole batch
        end %re_mm 
    end   %re_mm 
    if ((length(MRSCont.files_mm) ~= MRSCont.nDatasets(1)) )   %re_mm 
        msg = 'Number of specified MM files does not match number of specified metabolite files.'; %re_mm 
        fprintf(msg);
        error(msg);
    end   %re_mm 
end   %re_mm 
if MRSCont.flags.hasRef
    if length(MRSCont.files_ref) ~= MRSCont.nDatasets(1)
        msg = 'Number of specified reference files does not match number of specified metabolite files.'; %re_mm 
        fprintf(msg);
        error(msg);
    end
end
if MRSCont.flags.hasWater
    if length(MRSCont.files_w) ~= MRSCont.nDatasets(1)
        msg = 'Number of specified water files does not match number of specified metabolite files.'; %re_mm 
        fprintf(msg);
        error(msg);
    end
end

%% Get the data (loop over all datasets)
refLoadTime = tic;
if MRSCont.flags.isGUI
    progressText = MRSCont.flags.inProgress;
else
    progressText = '';
end
for kk = 1:MRSCont.nDatasets(1)
     for ll = 1: 1:MRSCont.nDatasets(2)
        [~] = printLog('OspreyLoad',kk,ll,MRSCont.nDatasets,progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI);   
        if ~(MRSCont.flags.didLoad == 1 && MRSCont.flags.speedUp && isfield(MRSCont, 'raw') && (kk > length(MRSCont.raw))) || ~strcmp(MRSCont.ver.Osp,MRSCont.ver.CheckOsp)

            % Read in the raw metabolite data. Since the Philips SDAT loader needs
            % to know the number of sub-spectra (e.g. from spectral editing), the
            % type of sequence needs to be differentiated here already.
            metab_ll = MRSCont.opts.MultipleSpectra.metab(ll);
            if MRSCont.flags.isUnEdited
                raw         = io_loadspec_sdat(MRSCont.files{metab_ll,kk},1,MRSCont.flags.isSERIES);
                raw.flags.isUnEdited = 1;
            elseif MRSCont.flags.isMEGA
                raw         = io_loadspec_sdat(MRSCont.files{metab_ll,kk},2,MRSCont.flags.isSERIES);
                raw.flags.isMEGA = 1;
            elseif MRSCont.flags.isHERMES
                raw         = io_loadspec_sdat(MRSCont.files{metab_ll,kk},4,MRSCont.flags.isSERIES);
                raw.flags.isHERMES = 1;
            elseif MRSCont.flags.isHERCULES
                raw         = io_loadspec_sdat(MRSCont.files{metab_ll,kk},4,MRSCont.flags.isSERIES);
                raw.flags.isHERCULES = 1;
            end
            % Add NIfTI-MRS information
            raw                           = osp_add_nii_mrs_field(raw,MRSCont.ver.Osp);
            MRSCont.raw{metab_ll,kk}      = raw;

            % Read in the raw MM data. re_mm
            if MRSCont.flags.hasMM %re_mm
                temp_ll = MRSCont.opts.MultipleSpectra.mm(ll);
                if MRSCont.flags.isUnEdited %re_mm                    
                    raw_mm = io_loadspec_sdat(MRSCont.files_mm{temp_ll,kk},1,MRSCont.flags.isSERIES); %re_mm
                    [raw_mm] = op_rmempty(raw_mm); %re_mm
                    raw_mm.flags.isUnEdited = 1;
                elseif MRSCont.flags.isMEGA %re_mm
                    raw_mm = io_loadspec_sdat(MRSCont.files_mm{temp_ll,kk},2,MRSCont.flags.isSERIES); %re_mm
                    raw_mm.flags.isMEGA = 1;
                elseif MRSCont.flags.isHERMES%re_mm
                    raw_mm = io_loadspec_sdat(MRSCont.files_mm{temp_ll,kk},1,MRSCont.flags.isSERIES); %re_mm
                    raw_mm.flags.isHERMES = 1;
                elseif MRSCont.flags.isHERCULES %re_mm
                    raw_mm = io_loadspec_sdat(MRSCont.files_mm{temp_ll,kk},1,MRSCont.flags.isSERIES); %re_mm
                    raw_mm.flags.isHERCULES = 1;
                end
                % Add NIfTI-MRS information
                raw_mm                      = osp_add_nii_mrs_field(raw_mm,MRSCont.ver.Osp);
                MRSCont.raw_mm{temp_ll,kk}  = raw_mm;
            end %re_mm      

            % Read in the raw reference data.
            if MRSCont.flags.hasRef
                ref_ll = MRSCont.opts.MultipleSpectra.ref(ll);
                if MRSCont.flags.isUnEdited                    
                    raw_ref = io_loadspec_sdat(MRSCont.files_ref{ref_ll,kk},1,MRSCont.flags.isSERIES);
                    raw_ref = op_combine_water_subspecs(raw_ref,0);
                    raw_ref.flags.isUnEdited = 1;
                elseif MRSCont.flags.isMEGA
                    try % GO 03042024: this works for the JHU patch only but throws an error for product MEGA
                        raw_ref = io_loadspec_sdat(MRSCont.files_ref{ref_ll,kk},2,MRSCont.flags.isSERIES);
                    catch % GO 03042024: this works for product MEGA
                        raw_ref = io_loadspec_sdat(MRSCont.files_ref{ref_ll,kk},1,MRSCont.flags.isSERIES);
                    end
                    raw_ref = op_combine_water_subspecs(raw_ref,0);
                    raw_ref.flags.isMEGA = 1;
                elseif MRSCont.flags.isHERMES
                    raw_ref = io_loadspec_sdat(MRSCont.files_ref{ref_ll,kk},1,MRSCont.flags.isSERIES);
                    raw_ref = op_combine_water_subspecs(raw_ref,0);
                    raw_ref.flags.isHERMES = 1;
                 elseif MRSCont.flags.isHERCULES
                    raw_ref = io_loadspec_sdat(MRSCont.files_ref{ref_ll,kk},1,MRSCont.flags.isSERIES);
                    raw_ref = op_combine_water_subspecs(raw_ref,0);
                    raw_ref.flags.isHERCULES = 1;
                end
                % Add NIfTI-MRS information
                raw_ref                     = osp_add_nii_mrs_field(raw_ref,MRSCont.ver.Osp);
                MRSCont.raw_ref{ref_ll,kk}  = raw_ref;
            end
            if MRSCont.flags.hasWater
                w_ll = MRSCont.opts.MultipleSpectra.w(ll);
                raw_w   = io_loadspec_sdat(MRSCont.files_w{w_ll,kk},1,MRSCont.flags.isSERIES);
                raw_w = op_combine_water_subspecs(raw_w,0);
                raw_w.flags.isUnEdited = 1;
                % Add NIfTI-MRS information
                raw_w                     = osp_add_nii_mrs_field(raw_w,MRSCont.ver.Osp);
                MRSCont.raw_w{w_ll,kk}    = raw_w;
            end

            % Read in the MM reference data.
            if MRSCont.flags.hasMMRef
                temp_ll = MRSCont.opts.MultipleSpectra.mm_ref(ll);
                if MRSCont.flags.isUnEdited
                    raw_mm_ref = io_loadspec_sdat(MRSCont.files_mm_ref{temp_ll,kk},1,MRSCont.flags.isSERIES);
                    raw_mm_ref = op_combine_water_subspecs(raw_mm_ref,0);
                    raw_mm_ref.flags.isUnEdited = 1;
                elseif MRSCont.flags.isMEGA
                    raw_mm_ref = io_loadspec_sdat(MRSCont.files_mm_ref{temp_ll,kk},2,MRSCont.flags.isSERIES);
                    raw_mm_ref = op_combine_water_subspecs(raw_mm_ref,0);
                    raw_mm_ref.flags.isMEGA = 1;
                elseif MRSCont.flags.isHERMES
                    raw_mm_ref = io_loadspec_sdat(MRSCont.files_mm_ref{temp_ll,kk},1,MRSCont.flags.isSERIES);
                    raw_mm_ref = op_combine_water_subspecs(raw_mm_ref,0);
                    raw_mm_ref.flags.isHERMES = 1;
                 elseif MRSCont.flags.isHERCULES
                    raw_mm_ref = io_loadspec_sdat(MRSCont.files_mm_ref{temp_ll,kk},1,MRSCont.flags.isSERIES);
                    raw_mm_ref = op_combine_water_subspecs(raw_mm_ref,0);
                    raw_mm_ref.flags.isHERCULES = 1;
                end
                % Add NIfTI-MRS information
                raw_mm_ref                      = osp_add_nii_mrs_field(raw_mm_ref,MRSCont.ver.Osp);
                MRSCont.raw_mm_ref{temp_ll,kk}  = raw_mm_ref;
            end
        end
    end
end
time = toc(refLoadTime);
[~] = printLog('done',time,MRSCont.nDatasets(1),MRSCont.nDatasets(2),progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI); 
% Set flag
MRSCont.flags.coilsCombined     = 1;
MRSCont.runtime.Load = time;
end%io_loadspec_sdat.m
%Jamie Near, McGill University 2014.
%Georg Oeltzschner, Johns Hopkins University 2018.
%
% USAGE:
% out=io_loadspec_sdat(filename,subspecs);
% 
% DESCRIPTION:
% Reads in Philips MRS data (.spar and .sdat files) using code adapted from 
% PhilipsRead.m, provided as part of the Gannet software package by Richard 
% Edden (gabamrs.com).
% 
% io_loadspec_sdat outputs the data in structure format, with fields 
% corresponding to time scale, fids, frequency scale, spectra, and header 
% fields containing information about the acquisition.  The resulting 
% matlab structure can be operated on by the other functions in this MRS 
% toolbox. ALSO:  This code is not currently smart enough to parse out all 
% of the relevant information from the header file, such as the number of 
% subspectra.  So for now, these details must be passed to the function as 
% input arguments.  Help implementing these improvements are most welcome!!
% 
% INPUTS:
% filename   = filename of Philips sdat file to be loaded.
% subspecs   = number of subspectra in the data (from spectral editing, ISIS, etc.)
%
% OUTPUTS:
% out        = Input dataset in FID-A structure format.

function out = io_loadspec_sdat(filename,subspecs,series)

if nargin<3
    series = 0;
end
% Read in the data and header information
[data, header] = philipsLoad(filename);

% Determine the dimensions of the data
data_size       = size(data);
dims.t          = find(data_size == header.samples);
if (header.rows > 1 && header.averages > 1) && series
    if length(data_size) > 2 % Data has averages and series
        dims.averages   = find(data_size == header.averages);
        dims.extras   = find(data_size == header.rows);
    else % Data has a series stored
        dims.averages   = 0;
        dims.extras   = find(data_size == header.rows);
    end
else
    dims.averages   = find(data_size == header.rows);
end
dims.coils      = 0; % SDAT is already coil-combined
% Now arrange in the standard order (samples-avgs-subspecs):
if (isfield(header, 'nr_of_slices_for_multislice') && header.nr_of_slices_for_multislice > 1) && (isfield(header, 'dim2_pnts') && header.dim2_pnts' > 1)
    data = permute(data ,[dims.t dims.averages dims.Zvoxels]);  
    dims.Zvoxels = 3;
    dims.averages = 2;
    dims.extras = 0;
else if (header.rows > 1 && header.averages > 1) && series
        if length(data_size) > 2 % Data has averages and series
            data = permute(data ,[dims.t dims.extras dims.averages]);
            dims.averages = 2;
            dims.extras = 3;
        else % Data has a series stored
            data = permute(data ,[dims.t dims.extras]);
            dims.averages = 0;
            dims.extras = 2;
        end
    else
        data = permute(data ,[dims.t dims.averages]);
        dims.averages = 2;
        dims.extras = 0;
    end
end

dims.t = 1;


% We have no way of actually knowing the number of sub-spectra (e.g. for 
% MEGA-PRESS or HERMES acquisitions, so we will split the averages 
% according to the 'subspecs' input.
% Initialize fids array:
fids = squeeze(zeros(header.samples, header.rows/subspecs, subspecs));
% Remove phase cycle
fids = fids .* repmat(conj(fids(1,:,:,:))./abs(fids(1,:,:,:)),[size(fids,1) 1]);
if subspecs == 2
    %Split the subspectra out of the "averages" dimension:
    fids(:,:,1) = data(:,[1:2:end]);
    fids(:,:,2) = data(:,[2:2:end]);
elseif subspecs == 4
    fids(:,:,1) = data(:,[1:4:end]);
    fids(:,:,2) = data(:,[2:4:end]);
    fids(:,:,3) = data(:,[3:4:end]);
    fids(:,:,4) = data(:,[4:4:end]);
else
    fids = data;
end

if subspecs > 1
    dims.subSpecs = 3;
else
    dims.subSpecs = 0;
end

sz = size(fids);

% Fill in the header information
txfrq = header.synthesizer_frequency; % transmitter frequency [Hz]
Bo = txfrq/42577000; % B0 [T]
averages = size(fids,2)*size(fids,3); % number of rows in the file
rawAverages = averages;
spectralwidth = header.sample_frequency; % bandwidth [Hz]
dwelltime = 1/spectralwidth; % dwelltime [s]
te = header.echo_time; % echo time [ms]
tr = header.repetition_time; % repetition time [ms]
sequence = header.scan_id; % sequence type
Ncoils = 1; % SDAT already coil-combined
rawSubspecs = subspecs;
date = header.scan_date; % scan date [yyyy.mm.dd hh:mm:ss]
geometry.size.ap = header.ap_size; % voxel size in AP direction [mm]
geometry.size.lr = header.lr_size; % voxel size in LR direction [mm]
geometry.size.cc = header.cc_size; % voxel size in CC direction [mm]
geometry.pos.ap = header.ap_off_center; % voxel center offset in AP direction [mm]
geometry.pos.lr = header.lr_off_center; % voxel center offset in LR direction [mm]
geometry.pos.cc = header.cc_off_center; % voxel center offset in CC direction [mm]
geometry.rot.ap = header.ap_angulation; % angulation around AP axis [deg]
geometry.rot.lr = header.lr_angulation; % angulation around LR axis [deg]
geometry.rot.cc = header.cc_angulation; % angulation around CC axis [deg]

% Produce specs
specs = fftshift(fft(fids,[],dims.t),dims.t);
% Calculate t and ppm arrays using the calculated parameters:
f = [(-spectralwidth/2)+(spectralwidth/(2*sz(1))):spectralwidth/(sz(1)):(spectralwidth/2)-(spectralwidth/(2*sz(1)))];
ppm = f/(Bo*42.577);

% Philips data assumes the center frequency to be 4.68 ppm:
centerFreq = 4.68;
ppm=ppm + centerFreq;

t = [0:dwelltime:(sz(1)-1)*dwelltime];

%FILLING IN DATA STRUCTURE
out.fids=fids;
out.specs=specs;
out.sz=sz;
out.ppm=ppm;  
out.t=t;    
out.spectralwidth=spectralwidth;
out.dwelltime=dwelltime;
out.txfrq=txfrq;
out.date=date;
out.dims=dims;
out.Bo=Bo;
out.averages=averages;
out.rawAverages=rawAverages;
out.subspecs=subspecs;
out.rawSubspecs=rawSubspecs;
out.seq=sequence;
out.te=te;
out.tr=tr;
out.pointsToLeftshift=0;
out.centerFreq = centerFreq;
out.geometry = geometry;
if isfield(header,'nucleus')
    out.nucleus = header.nucleus;
end
if isfield(header,'equipment_sw_verions')
    out.software = ['R ' header.equipment_sw_verions];
end
%FILLING IN DATA STRUCUTRE FOR SDAT MRSI
if isfield(header, 'dim2_pnts')
    out.nXvoxels = header.dim2_pnts;
    out.flags.MultiVoxel=1;
end
if isfield(header, 'dim3_pnts')
    out.nYvoxels = header.dim3_pnts;
    out.flags.MultiVoxel=1;
end
if isfield(header, 'nr_of_slices_for_multislice') && isfield(header, 'dim2_pnts');
    out.nZvoxels = header.nr_of_slices_for_multislice;
    out.flags.MultiVoxel=1;
end

%FILLING IN THE FLAGS
out.flags.writtentostruct=1;
out.flags.gotparams=1;
out.flags.leftshifted=0;
out.flags.filtered=0;
out.flags.zeropadded=0;
out.flags.freqcorrected=0;
out.flags.phasecorrected=0;
out.flags.averaged=0;
out.flags.addedrcvrs=1;
out.flags.subtracted=0;
out.flags.writtentotext=0;
out.flags.downsampled=0;
if out.dims.subSpecs==0
    out.flags.isFourSteps=0;
else
    out.flags.isFourSteps=(out.sz(out.dims.subSpecs)==4);
end
if dims.extras > 0 % Is a series
   out.extras = out.sz(dims.extras);
   extra_names = {};
   seq = {};
   for ex = 1 : out.sz(dims.extras)
       extra_names{ex} = ['Exp_' num2str(ex)];
       seq{ex} = out.seq;
   end
   out.extra_names = extra_names;
   if dims.averages == 0
      out.averages=1;
      out.flags.averaged = 1;
   end
   out.spectralwidth = ones(1,out.extras)*spectralwidth;
   out.dwelltime = ones(1,out.extras)*dwelltime;
   out.txfrq = ones(1,out.extras)*txfrq;
   out.exp_var = ones(1,out.extras);
   out.seq = seq;
   out.te = ones(1,out.extras)*te;
   out.tr = ones(1,out.extras)*tr;
   out.pointsToLeftshift = zeros(1,out.extras);
   out.centerFreq = ones(1,out.extras)*centerFreq;   
   out.flags.isSeries = 1;
   out.flags.MultiVoxel=0;
end
% Add info for niiwrite
out.PatientPosition = strrep([header.patient_position ' ' header.patient_orientation],'"','');
out.Manufacturer = 'Philips';
[~,filename,ext] = fileparts(filename);
out.OriginalFile = [filename ext];
% Sequence flags
out.flags.isUnEdited = 0;
out.flags.isMEGA = 0;
out.flags.isHERMES = 0;
out.flags.isHERCULES = 0;
out.flags.isPRIAM = 0;
out.flags.isMRSI = 0;
%DONE
% op_combinesubspecs.m
% Jamie Near, McGill University 2014.
% 
% USAGE:
% out=op_combinesubspecs(in,mode);
% 
% DESCRIPTION:
% Combine the subspectra in an acquisition either by addition or
% subtraction.
% 
% INPUTS:
% in        = input data in matlab structure format.
% mode      = -"diff" adds the subspectra together (this is counter intuitive,
%             but the reason is that many "difference editing" sequences use phase
%             cycling of the readout ADC to achieve "subtraction by addition".
%             -"summ" performs a subtraction of the subspectra.
%
% OUTPUTS:
% out       = Output following combination of subspectra.  

function out=op_combinesubspecs(in,mode);

if in.flags.subtracted
    error('ERROR:  Subspectra have already been combined!  Aborting!');
end
if in.flags.isFourSteps
    error('ERROR: data with four steps must first be converted using op_fourStepCombine.m!  Aborting!');
end

% if ~in.flags.freqcorrected
%     disp('WARNING:  Frequency correction has not yet been performed!');
% end
% if ~in.flags.phasecorrected
%     disp('WARNING:  Phase correction has not yet been performed!');
% end


if mode=='diff'
    %add the spectrum along the subSpecs dimension;
    fids=sum(in.fids,in.dims.subSpecs);
    fids=fids/in.sz(in.dims.subSpecs); %divide by number of subspecs so that this is an averaging operation;
elseif mode=='summ'
    %subtract the spectrum along the subSpecs dimension;
    fids=diff(in.fids,1,in.dims.subSpecs);
    fids=fids/in.sz(in.dims.subSpecs); %divide by nymber of subspecs so that this is an averaging operation;
end

fids=squeeze(fids);

%re-calculate Specs using fft
specs=fftshift(fft(fids,[],in.dims.t),in.dims.t);

%change the dims variables
if in.dims.t>in.dims.subSpecs
    dims.t=in.dims.t-1;
else
    dims.t=in.dims.t;
end
if in.dims.coils>in.dims.subSpecs
    dims.coils=in.dims.coils-1;
else
    dims.coils=in.dims.coils;
end
if in.dims.averages>in.dims.subSpecs
    dims.averages=in.dims.averages-1;
else
    dims.averages=in.dims.averages;
end
dims.subSpecs=0;
if in.dims.extras>in.dims.subSpecs
    dims.extras=in.dims.extras-1;
else
    dims.extras=in.dims.extras;
end

%re-calculate the sz variable
sz=size(fids);


%FILLING IN DATA STRUCTURE
out=in;
out.fids=fids;
out.specs=specs;
out.sz=sz;
out.dims=dims;
out.subspecs=1;
out.averages=in.averages/2;

%FILLING IN THE FLAGS
out.flags=in.flags;
out.flags.writtentostruct=1;
out.flags.subtracted=1;
function [out] = osp_editSubSpecAlign(varargin)
%% [varargout] = osp_editSubSpecAlign(varargin)
%   Aligns sub-spectra of (multiplexed) edited MRS data to minimize
%   subtraction artefacts.
%
%   USAGE:
%       [outA, outB, outC, outD] = osp_editSubSpecAlign(in, seq, target,unstableWater);
%
%   INPUTS:
%       in        = Input data structure with sub-spectrum A.
%       seq       = sequence type
%       target     = String. Can be 'GABA' or 'GSH'. (necessary if only two
%                    inputs inA and inB are provided)
%       unstableWater = Flag for unstable residual water. This ignores
%                       water for the optimization and uses Choline instead
%
%   OUTPUTS:
%       outA       = Output following alignment of averages.
%       outB       = Output following alignment of averages.
%       outC       = Output following alignment of averages. (optional)
%       outD       = Output following alignment of averages. (optional)
%
%   AUTHOR:
%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-08-15)
%       goeltzs1@jhmi.edu
%       Dr. Mark Mikkelsen (Johns Hopkins University)
%       mmikkel5@jhmi.edu
%   
%   CREDITS:    
%       This code is based on numerous functions from the FID-A toolbox by
%       Dr. Jamie Near (McGill University)
%       https://github.com/CIC-methods/FID-A
%       Simpson et al., Magn Reson Med 77:23-33 (2017)
%
%   HISTORY:
%       2019-08-15: First version of the code.


% Determine whether there are 2 (MEGA) or 4 (HERMES/HERCULES) inputs
if nargin == 5
    in     = varargin{1};
    seqType = varargin{2};
    target1 = varargin{3};
    target2 = varargin{4};
    unstableWater = varargin{5};
elseif nargin == 4 && (strcmp(varargin{2},'HERMES') || strcmp(varargin{2},'HERCULES'))
    in     = varargin{1};
    seqType = varargin{2};
    target1 = varargin{3};
    target2 = varargin{4};
    unstableWater = 0;
elseif nargin == 4
    in     = varargin{1};
    seqType = varargin{2};
    target = varargin{3};
    unstableWater = varargin{4};
elseif nargin == 3 && strcmp(varargin{2},'MEGA')
    in     = varargin{1};
    seqType = varargin{2};
    target  = varargin{3};
    unstableWater = 0;
else
    error('Error in osp_editSubSpecAlign! For provide raw data struct, the sequence type, the name of the editing target, and the optional unstable water flag.')
end

% Check whether data is coil-combined. If not, throw error.
if ~in.flags.addedrcvrs
    error('ERROR:  I think it only makes sense to do this after you have combined the channels using op_addrcvrs.  ABORTING!!');
end

% Check whether data is averaged. If not, throw error.
if ~in.flags.averaged
    error('ERROR:  I think it only makes sense to do this after averaging using op_averaging.  ABORTING!!');
end

switch seqType
   case 'MEGA'
        inA=op_takesubspec(in,1);
        inB=op_takesubspec(in,2);
    case 'HERMES'
        inA=op_takesubspec(in,1);
        inB=op_takesubspec(in,2);
        inC=op_takesubspec(in,3);
        inD=op_takesubspec(in,4);
    case 'HERCULES'
        inA=op_takesubspec(in,1);
        inB=op_takesubspec(in,2);
        inC=op_takesubspec(in,3);
        inD=op_takesubspec(in,4);
end


%%% 1. SET UP REQUIRED VARIABLES %%%
% Define the frequency ranges over which water, NAA, and Cho subtraction artefacts
% are to be minimized. Also, get a good starting estimate for the frequency
% alignment shift by determining the difference between the two maxima in
% the respective peak range (water, NAA, or Cho).
freq = inA.ppm;
% Water
freqLim(1,:) = freq <= 4.68+0.22 & freq >= 4.68-0.22;
[~,i] = max([abs(real(inA.specs(freqLim(1,:)))) abs(real(inB.specs(freqLim(1,:))))]);
freq2 = freq(freqLim(1,:));
maxFreq = freq2(i);
for jj = 1:2
    tmp(jj,:) = freq <= maxFreq(jj)+0.22 & freq >= maxFreq(jj)-0.22;
end
freqLim(1,:) = or(tmp(1,:), tmp(2,:));
f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
x0(1,:) = [f0 0];

% NAA
freqLim(2,:) = freq <= 2.01+0.13 & freq >= 2.01-0.13;
peaks = '2.01 ppm (A/B)';
switch seqType
    case 'HERCULES'
        [~,i] = max([abs(real(inA.specs(freqLim(2,:)))) abs(real(inC.specs(freqLim(2,:))))]);
    case 'HERMES'
        [~,i] = max([abs(real(inA.specs(freqLim(2,:)))) abs(real(inC.specs(freqLim(2,:))))]);
    case 'MEGA'
        [~,i] = max([abs(real(inA.specs(freqLim(2,:)))) abs(real(inB.specs(freqLim(2,:))))]);
end
freq2 = freq(freqLim(2,:));
maxFreq = freq2(i);
for jj = 1:2
    tmp(jj,:) = freq <= maxFreq(jj)+0.13 & freq >= maxFreq(jj)-0.13;
end
freqLim(2,:) = or(tmp(1,:), tmp(2,:));
f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
x0(2,:) = [f0 0];

% In case the water peak is not well-behaved and has several peaks we are
% possibly detecting several peaks. This will lead to unreasonable shifts
% between the sub-spectra. In this case, we use the Choline peak.
if unstableWater

    freqLim(1,:) = freq <= 3.22+0.09 & freq >= 3.22-0.09;
    [~,i] = max([abs(real(inA.specs(freqLim(1,:)))) abs(real(inB.specs(freqLim(1,:))))]);
    freq2 = freq(freqLim(1,:));
    maxFreq = freq2(i);
    for jj = 1:2
        tmp(jj,:) = freq <= maxFreq(jj)+0.08 & freq >= maxFreq(jj)-0.08;
    end
    freqLim(1,:) = or(tmp(1,:), tmp(2,:));
    f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
    x0(1,:) = [f0 0];

end

% Optimization options
lsqnonlinopts = optimoptions(@lsqnonlin);
lsqnonlinopts = optimoptions(lsqnonlinopts,'Display','off','Algorithm','levenberg-marquardt');

% Initialize common variables
t           = inA.t;


%%% 2. PERFORM ALIGNMENT BASED ON SEQUENCE TYPE
if strcmp(seqType, 'HERMES') || strcmp(seqType, 'HERCULES') 
    if ~(exist('target1','var') && exist('target2','var'))
        %Fall back into default HERMES GABA GSH editing
        target1 = 'GABA';
        target2 = 'GSH';
    end

    target = [target1 target2];
    switch target
        case {'GABAGSH','GABALac','GABAEtOH'}  
            % For HERMES/HERCULES data, align the GSH-OFF spectra first, i.e.
            % minimize the residual water peak in the difference between them.

            % Determine normalization factor so that normalized spectra are entered
            % into the optimization
            a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(1,:), t, x);
            param(1,:) = lsqnonlin(fun, x0(1,:), [], [], lsqnonlinopts);
            % Apply the calculated frequency/phase adjustment to the inB spectrum
            fidsB = inB.fids.*exp(1i*pi*(t'*param(1,1)*2+param(1,2)/180));
            specsB = fftshift(fft(fidsB, [], inB.dims.t), inB.dims.t);
            % Create output
            outA = inA;
            outB = inB;
            outB.fids = fidsB;
            outB.specs = specsB;

            % Then, align the GABA-OFF spectra, i.e minimize the residual NAA peak
            % in the difference between them.
            % Determine normalization factor so that normalized spectra are entered
            % into the optimization
            a = max(max([abs(real(inA.specs)) abs(real(inC.specs))]));
            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inC, 1/a), freqLim(2,:), t, x);
            param(2,:) = lsqnonlin(fun, x0(2,:), [], [], lsqnonlinopts);
            % Apply the calculated frequency/phase adjustment to the inC spectrum
            fidsC = inC.fids.*exp(1i*pi*(t'*param(2,1)*2+param(2,2)/180));
            specsC = fftshift(fft(fidsC, [], inC.dims.t), inC.dims.t);
            % Create output
            outC = inC;
            outC.fids = fidsC;
            outC.specs = specsC;

            % Then, align the GABA-ON-GSH-ON spectra to the **corrected** GABA-OFF-GSH-ON
            % spectrum - this is something Mark/Georg independently from each other
            % found out to work best for HERMES/HERCULES data.

            % Find Cho peak and get starting estimate for the frequency shift
            freqLim(3,:) = freq <= 3.2+0.09 & freq >= 3.2-0.09;
            [~,i] = max([abs(real(outC.specs(freqLim(3,:)))) abs(real(inD.specs(freqLim(3,:))))]);
            freq2 = freq(freqLim(3,:));
            maxFreq = freq2(i);
            for jj = 1:2
                tmp(jj,:) = freq <= maxFreq(jj)+0.08 & freq >= maxFreq(jj)-0.08;
            end
            freqLim(3,:) = or(tmp(1,:), tmp(2,:));
            f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
            x0(3,:) = [f0 0];

            % Determine normalization factor so that normalized spectra are entered
            % into the optimization
            a = max(max([abs(real(outC.specs)) abs(real(inD.specs))]));
            fun = @(x) objFunc(op_ampScale(outC, 1/a), op_ampScale(inD, 1/a), freqLim(3,:), t, x);
            param(3,:) = lsqnonlin(fun, x0(3,:), [], [], lsqnonlinopts);
            % Apply the calculated frequency/phase adjustment to the inD spectrum
            fidsD = inD.fids.*exp(1i*pi*(t'*param(3,1)*2+param(3,2)/180));
            specsD = fftshift(fft(fidsD, [], inD.dims.t), inD.dims.t);

            % Create output
            outD = inD;
            outD.fids = fidsD;
            outD.specs = specsD;

        case 'NAANAAG' 
            % For HERMES/HERCULES data, align the GSH-OFF spectra first, i.e.
            % minimize the residual water peak in the difference between them.
            % NAA
            freqLim(1,:) = freq <= 2.01+0.13 & freq >= 2.01-0.13;
            [~,i] = max([abs(real(inA.specs(freqLim(1,:)))) abs(real(inB.specs(freqLim(1,:))))]);
            freq2 = freq(freqLim(1,:));
            maxFreq = freq2(i);
            for jj = 1:2
                tmp(jj,:) = freq <= maxFreq(jj)+0.13 & freq >= maxFreq(jj)-0.13;
            end
            freqLim(1,:) = or(tmp(1,:), tmp(2,:));
            f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
            x0(1,:) = [f0 0];
            % Determine normalization factor so that normalized spectra are entered
            % into the optimization
            a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(1,:), t, x);
            param(1,:) = lsqnonlin(fun, x0(1,:), [], [], lsqnonlinopts);
            % Apply the calculated frequency/phase adjustment to the inB spectrum
            fidsB = inB.fids.*exp(1i*pi*(t'*param(1,1)*2+param(1,2)/180));
            specsB = fftshift(fft(fidsB, [], inB.dims.t), inB.dims.t);
            % Create output
            outA = inA;
            outB = inB;
            outB.fids = fidsB;
            outB.specs = specsB;

            % Then, align the GABA-OFF spectra, i.e minimize the residual NAA peak
            % in the difference between them.
