    68	function [ppm, spectra] = task005_build_spectra(case_data)
    69	npts = case_data.num_points;
    70	ppm = linspace(case_data.ppm_min, case_data.ppm_max, npts)';
    71	reference_shape = exp(-0.5 .* ((ppm - case_data.reference_center_ppm) ./ case_data.reference_width_ppm) .^ 2);
    72	edited_shape = exp(-0.5 .* ((ppm - case_data.edited_center_ppm) ./ case_data.edited_width_ppm) .^ 2);
    73	
    74	nsubs = numel(case_data.reference_amplitudes);
    75	spectra = zeros(npts, nsubs);
    76	for idx = 1:nsubs
    77	    phase = case_data.phase_degrees(idx) * pi / 180;
    78	    signal = case_data.reference_amplitudes(idx) .* reference_shape + ...
    79	        case_data.edited_amplitudes(idx) .* edited_shape;
    80	    spectra(:, idx) = real(signal .* complex(cos(phase), sin(phase)));
    81	end
    82	end
