   110	function polarity = task005_estimate_polarity(spec)
   111	[~, idx] = max(abs(real(spec)));
   112	if real(spec(idx)) >= 0
   113	    polarity = 1.0;
   114	else
   115	    polarity = -1.0;
   116	end
   117	end
