     2	% Jamie Near, McGill University 2014.
     3	% 
     4	% USAGE:
     5	% out=op_addScans(in1,combMatrix);
     6	% 
     7	% DESCRIPTION:
     8	% Add or subtract two scans together.
     9	% 
    10	% INPUTS:
    11	% in        = Spectrum (in matlab structure format)
    12	% combMatrix	 = How to combine the spectra
    13	%
    14	% OUTPUTS:
    15	% out        = Result of adding inputs in1 and in2.  
    16	
    17	
    18	function out=op_HadamardScans(in,combMatrix,name);
    19	
    20	dim = in.dims.subSpecs;
    21	
    22	if ~isempty(fieldnames(in))
    23	    if dim == 2
    24	        if length(combMatrix) == 2
    25	            fids = combMatrix(1)*in.fids(:,1) + combMatrix(2)*in.fids(:,2);
    26	        end
    27	        if length(combMatrix) == 4
    28	            fids = combMatrix(1)*in.fids(:,1) + combMatrix(2)*in.fids(:,2) + combMatrix(3)*in.fids(:,3)+ combMatrix(4)*in.fids(:,4);
    29	        end
    30	    end
    31	end
    32	
    33	%re-calculate Specs using fft
    34	specs=fftshift(fft(fids,[],in.dims.t),in.dims.t);
    35	
    36	out=in;
    37	if ~contains(in.names,name)
    38	        out.fids=cat(dim,in.fids,fids);
    39	        out.specs=cat(dim,in.specs,specs);
    40	        out.sz=size(fids);            
    41	        out.names{end+1} = name;
    42	        out.subspecs = out.subspecs + 1;
    43	    else
    44	        ind = find(strcmp(out.names,name));
    45	        out.fids(:,ind,:,:,:,:,:) = fids(:,1,:,:,:,:,:);
    46	        out.specs(:,ind,:,:,:,:,:) = specs(:,1,:,:,:,:,:);
    47	end
