     3	% 
     4	% USAGE:
     5	% out=op_ampScale(in,A);
     6	% 
     7	% DESCRIPTION:
     8	% Scale the amplitude of a spectrum by factor A.
     9	% 
    10	% INPUTS:
    11	% in    = input data in matlab structure format
    12	% A     = Amplitude scaling factor.
    13	%
    14	% OUTPUTS:
    15	% out   = Output following amplitude scaling.  
    16	
    17	function out=op_ampScale(in,A);
    18	
    19	sz_A = length(A);
    20	out=in;
    21	if sz_A == 1
    22	    out.specs=in.specs*A;
    23	    out.fids=in.fids*A;
    24	else
    25	    
    26	    if in.dims.averages==0   
    27	        for ss = 1 : out.sz(end)
    28	            out.specs(:,ss)=in.specs(:,ss)*A(ss);
    29	            out.fids(:,ss)=in.fids(:,ss)*A(ss);
    30	        end
    31	    else
    32	        for ss = 1 : out.sz(end)
    33	            out.specs(:,:,ss)=in.specs(:,:,ss)*A(ss);
    34	            out.fids(:,:,ss)=in.fids(:,:,ss)*A(ss);
    35	        end
    36	    end
    37	end
