168	function [max_w, max_NAA] = findMaxNAAw(in)
169	% This embedded function finds the maximum intensities of the water
170	% and NAA signals of an input spectrum.
171	
172	% Determine relevant frequency ranges
173	out_w   = op_freqrange(in,4.2,5.2);
174	out_NAA = op_freqrange(in,1.8,2.2);
175	
176	% Determine maximum absolute signal
177	max_w   = max([abs(max(real(out_w.specs))), abs(min(real(out_w.specs)))]);
178	max_NAA = max([abs(max(real(out_NAA.specs))), abs(min(real(out_NAA.specs)))]);
179	end
