     1	function [MRSCont] = OspreyProcess(MRSCont)
     2	%% [MRSCont] = OspreyProcess(MRSCont)
     3	%   This function pre-processes MRS data from all major vendors.
     4	%   Data is read from the provided input filenames. It is shaped,
     5	%   preprocessed, aligned, etc. according to the type of sequence
     6	%   (un-edited data, MEGA-edited (ON/OFF), HERMES/HERCULES (A/B/C/D),
     7	%   etc.).
     8	%
     9	%   USAGE:
    10	%       MRSCont = OspreyProcess(MRSCont);
    11	%
    12	%   INPUTS:
    13	%       MRSCont     = Osprey MRS data container.
    14	%
    15	%   OUTPUTS:
    16	%       MRSCont     = Osprey MRS data container.
    17	%
    18	%   AUTHOR:
    19	%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-02-19)
    20	%       goeltzs1@jhmi.edu
    21	%
    22	%   CREDITS:
    23	%       This code is based on numerous functions from the FID-A toolbox by
    24	%       Dr. Jamie Near (McGill University)
    25	%       https://github.com/CIC-methods/FID-A
    26	%       Simpson et al., Magn Reson Med 77:23-33 (2017)
    27	%
    28	%   HISTORY:
    29	%       2019-02-19: First version of the code.
    30	
    31	outputFolder = MRSCont.outputFolder;
    32	diary(fullfile(outputFolder, 'LogFile.txt'));
    33	
    34	% Checking for version, toolbox, and previously run modules
    35	[~,MRSCont.ver.CheckOsp ] = osp_CheckRunPreviousModule(MRSCont, 'OspreyProcess');
    36	
    37	
    38	%% Data post-processing starts here
    39	warning('off','all');
    40	
    41	% Loop over all datasets
    42	refProcessTime = tic;
    43	if MRSCont.flags.isGUI
    44	    progressText = MRSCont.flags.inProgress;
    45	else
    46	    progressText = '';
    47	end
    48	
    49	for kk = 1:MRSCont.nDatasets(1) %Subject loop
    50	    for ll = 1: 1:MRSCont.nDatasets(2) %Experiment loop
    51	        [~] = printLog('OspreyProcess',kk,ll,MRSCont.nDatasets(1),progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI);
    52	
    53	
    54	        if ~(MRSCont.flags.didProcess == 1 && MRSCont.flags.speedUp && isfield(MRSCont, 'processed') && (kk > size(MRSCont.processed.metab,2)))  || ~strcmp(MRSCont.ver.Osp,MRSCont.ver.CheckOsp)
    55	            metab_ll = MRSCont.opts.MultipleSpectra.metab(ll);
    56	%%          %%% 1. GET RAW DATA %%%
    57	            raw                         = MRSCont.raw{metab_ll,kk};                                          % Get the kk-th dataset
    58	
    59	            % Get sequence type set up
    60	            if raw.flags.isUnEdited
    61	                seq = 'unedited';
    62	            elseif raw.flags.isMEGA
    63	                seq = 'MEGA';
    64	            elseif raw.flags.isHERMES
    65	                seq = 'HERMES';
    66	            elseif raw.flags.isHERCULES
    67	                seq = 'HERCULES';
    68	            end
    69	
    70	%%          %%% 1B. GET MM DATA %%%
    71	            if MRSCont.flags.hasMM
    72	                mm_ll = MRSCont.opts.MultipleSpectra.mm(ll);
    73	                raw_mm                         = MRSCont.raw_mm{mm_ll,kk};              % Get the kk-th dataset re_mm
    74	                if raw_mm.averages > 1 && raw_mm.flags.averaged == 0 %re_mm
    75	                    [raw_mm,fs,phs]               = op_alignAverages(raw_mm, 1, 'n'); %re_mm
    76	                    raw_mm                     = op_averaging(raw_mm);            % Average re_mm
    77	                else %re_mm
    78	                    raw_mm.flags.averaged  = 1; %re_mm
    79	                    raw_mm.dims.averages   = 0; %re_mm
    80	                    fs = 0;
    81	                    phs = 0;
    82	                end
    83	                if raw_mm.flags.isUnEdited
    84	                    [raw_mm,~]                     = op_ppmref(raw_mm,4.6,4.8,4.68);  % Reference to water @ 4.68 ppm  %re_mm
    85	                end
    86	                if raw_mm.flags.isUnEdited
    87	                    raw_mm.names = {'A'};
    88	                    raw_mm.target = {''};
    89	                    raw_mm.specReg{1}.fs              = fs; % save align parameters
    90	                    raw_mm.specReg{1}.phs             = phs; % save align parameters
    91	                    raw_mm.specReg{1}.weights{1}         = ones(size(phs)); % save align parameters
    92	                    driftPre = 0;
    93	                end
    94	                if raw_mm.flags.isMEGA
    95	                    raw_mm.names = {'A','B'};
    96	                    raw_mm.target = MRSCont.opts.editTarget';
    97	                    raw_mm.specReg{1}.fs              = fs; % save align parameters
    98	                    raw_mm.specReg{1}.phs             = phs; % save align parameters
    99	                    raw_mm.specReg{1}.weights{1}         = ones(size(phs)); % save align parameters
   100	                    raw_mm.specReg{1}.weights{2}         = ones(size(phs)); % save align parameters
   101	                    driftPre{1} = 0;
   102	                    driftPre{2} = 0;
   103	                end
   104	                if raw_mm.flags.isHERMES || raw_mm.flags.isHERCULES
   105	                    raw_mm.names = {'A', 'B', 'C', 'D'};
   106	                    raw_mm.target = MRSCont.opts.editTarget';
   107	                    raw_mm.specReg{1}.fs              = fs; % save align parameters
   108	                    raw_mm.specReg{1}.phs             = phs; % save align parameters
   109	                    raw_mm.specReg{1}.weights{1}         = size(phs); % save align parameters
   110	                    raw_mm.specReg{1}.weights{2}         = size(phs); % save align parameters
   111	                    raw_mm.specReg{1}.weights{3}         = size(phs); % save align parameters
   112	                    raw_mm.specReg{1}.weights{4}         = size(phs); % save align parameters
   113	                    driftPre{1} = 0;
   114	                    driftPre{2} = 0;
   115	                    driftPre{3} = 0;
   116	                    driftPre{4} = 0;
   117	                end
   118	            end  %re_mm
   119	
   120	%%          %%% 1C. GET MM REFERENCE DATA %%%
   121	            if MRSCont.flags.hasMMRef
   122	                mm_ref_ll = MRSCont.opts.MultipleSpectra.mm_ref(ll);
   123	                raw_mm_ref = MRSCont.raw_mm_ref{mm_ref_ll,kk};              % Get the kk-th dataset
   124	                raw_mm_ref = op_combine_water_subspecs(raw_mm_ref);
   125	            end
   126	            
   127	%%          %%% 1D. GET REFERENCE DATA %%%
   128	            if MRSCont.flags.hasRef
   129	                ref_ll = MRSCont.opts.MultipleSpectra.ref(ll);
   130	                raw_ref = MRSCont.raw_ref{ref_ll,kk};              % Get the kk-th dataset
   131	                
   132	                % Combine SPECIAL sub-spectra
   133	                if MRSCont.flags.isSPECIAL
   134	                    raw_ref = combine_special_subspecs(raw_ref);
   135	                end
   136	
   137	                if raw_ref.averages > 1 && raw_ref.flags.averaged == 0
   138	                    [raw_ref,fs,phs]                 = op_alignAverages(raw_ref, 1, 'n');
   139	                    badAverages=find(abs(fs)>6);
   140	                    goodAverages=find(abs(fs)<6); 
   141	                    if ~isempty(badAverages)
   142	                        fs(badAverages) =[];
   143	                        phs(badAverages) =[];
   144	                        raw_ref.AveragesToKeep = goodAverages;
   145	                        raw_ref.fids=raw_ref.fids(:,goodAverages,:,:);
   146	                        raw_ref.specs=fftshift(ifft(raw_ref.fids,[],raw_ref.dims.t),raw_ref.dims.t);
   147	                        raw_ref.sz=size(raw_ref.fids);
   148	                        raw_ref.averages=length(goodAverages);
   149	                    end
   150	                    raw_ref                       = op_averaging(raw_ref);              % Average
   151	                    raw_ref.specReg{1}.fs              = fs; % save align parameters
   152	                    raw_ref.specReg{1}.phs             = phs; % save align parameters
   153	                else
   154	                    raw_ref.flags.averaged    = 1;
   155	                    raw_ref.dims.averages     = 0;
   156	                end
   157	            
   158	                raw_ref = op_combine_water_subspecs(raw_ref);                
   159	            end
   160	
   161	%%           %%% 1E. GET SHORT-TE WATER DATA %%%
   162	             % And do the processing
   163	             if MRSCont.flags.hasWater
   164	                w_ll = MRSCont.opts.MultipleSpectra.w(ll);
   165	                raw_w                           = MRSCont.raw_w{w_ll,kk};                % Get the kk-th dataset
   166	                
   167	                % Combine SPECIAL sub-spectra
   168	                if MRSCont.flags.isSPECIAL
   169	                    raw_w = combine_special_subspecs(raw_w);
   170	                end
   171	                
   172	                if raw_w.averages > 1 && raw_w.flags.averaged == 0
   173	                    [raw_w,fs,phs]                 = op_alignAverages(raw_w, 1, 'n');
   174	                    badAverages=find(abs(fs)>6);
   175	                    goodAverages=find(abs(fs)<6); 
   176	                    if ~isempty(badAverages)
   177	                        fs(badAverages) =[];
   178	                        phs(badAverages) =[];
   179	                        raw_w.AveragesToKeep = goodAverages;
   180	                        raw_w.fids=raw_w.fids(:,goodAverages,:,:);
   181	                        raw_w.specs=fftshift(ifft(raw_w.fids,[],raw_w.dims.t),raw_w.dims.t);
   182	                        raw_w.sz=size(raw_w.fids);
   183	                        raw_w.averages=length(goodAverages);
   184	                    end
   185	                    raw_w                       = op_averaging(raw_w);              % Average
   186	                    raw_w.specReg{1}.fs              = fs; % save align parameters
   187	                    raw_w.specReg{1}.phs             = phs; % save align parameters
   188	                else
   189	                    raw_w.flags.averaged    = 1;
   190	                    raw_w.dims.averages     = 0;
   191	                end
   192	
   193	                if raw_w.subspecs > 1
   194	                    raw_w = op_combine_water_subspecs(raw_w);
   195	                end
   196	                if ~MRSCont.flags.isMRSI
   197	                    [raw_w,~]                       = op_eccKlose(raw_w, raw_w);        % Klose eddy current correction
   198	                else
